column = 'Date'
operation = 'parse'
parse_format = '%B %d'

if df is None:
    raise ValueError("A DataFrame must be provided.")

if column not in df.columns:
    raise ValueError(f"Column Date not found in DataFrame.")

new_col = f'Date_parse'

try:
    if operation == 'parse':
        df[new_col] = pd.to_datetime(df[column], format = parse_format, errors='coerce')
    elif operation == 'convert_time_taken_to_seconds':
        df[new_col] = df[column].apply(lambda x: int(x.split(":")[0]) * 60 + float(x.split(":")[1]))
    else:
        # Ensure it is datetime first:
        dt_series = pd.to_datetime(df[column], errors='coerce')

        if operation == 'extract_year':
            df[new_col] = dt_series.dt.year
        elif operation == 'extract_month':
            df[new_col] = dt_series.dt.month
        elif operation == 'extract_day':
            df[new_col] = dt_series.dt.day
        elif operation == 'extract_weekday':
            df[new_col] = dt_series.dt.day_name()
        elif operation == 'to_timezone':
            if timezone is None:
                raise ValueError('timezone must be specified for timezone conversion.')
            df[new_col] = dt_series.dt.tz_localize('UTC').dt.tz_convert(timezone)
        elif operation == 'format':
            if date_format is None:
                raise ValueError('date_format must be specified for formatting.')
            df[new_col] = dt_series.dt.strftime(date_format)
        else:
            raise ValueError(f"Unsupported operation: 'parse'")
except:
    raise ValueError(f'Error in processing')

